    expect(res.status).toEqual(200);
    expect(await res.text()).toBe("asset:/test.png.gz");
    expect(Object.fromEntries(res.headers)).toMatchObject(expectedHeaders);
    expect(res.headers.get("content-length")).toBe("18");
  });

  it("Can serve asset (HEAD)", async () => {
    const headRes = await t.fetch("/test.png", {
      method: "HEAD",
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(headRes.status).toEqual(200);
    expect(await headRes.text()).toBe("");
    expect(Object.fromEntries(headRes.headers)).toMatchObject(expectedHeaders);
    expect(headRes.headers.get("content-length")).toBe("18");
  });

  it("Handles cache (if-none-match)", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "if-none-match": "w/123" },
    });
    expect(res.headers.get("etag")).toBe(expectedHeaders.etag);
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Handles cache (if-modified-since)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 404 if not found", async () => {
    const res = await t.fetch("/404/test.png");
    expect(res.status).toEqual(404);

    const headRes = await t.fetch("/404/test.png", { method: "HEAD" });
    expect(headRes.status).toEqual(404);
  });

  it("ignores if-modified-since when a non-matching if-none-match is present (RFC 9110 §13.1.3, #1454)", async () => {
    // If-None-Match takes precedence: it does not match, so a fresh 200 must be
    // returned even though If-Modified-Since alone would have produced a 304.
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/999",
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(200);
    expect(await res.text()).toContain("asset:/test.png");
  });

  it("Falls through to the next handler", async () => {
    const res = await t.fetch("/fallthrough/test.png");
    expect(res.status).toEqual(200);
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
  });

  it("Does not leak vary to the next handler", async () => {
    const res = await t.fetch("/fallthrough/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
    expect(res.headers.get("vary")).toBeNull();
  });
});

describeMatrix("serve static MIME types", (t, { it, expect }) => {
  beforeEach(() => {
    const serveStaticOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => `content for ${id}`),
      getMeta: vi.fn((id) => ({
        size: 10,
        path: id,
      })),
    };

    t.app.all("/**", (event) => {
      return serveStatic(event, serveStaticOptions);
    });
  });

  it("Uses custom getType function", async () => {
    const customOptions: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 10 })),
      getType: vi.fn((ext) => (ext === ".xyz" ? "application/custom" : undefined)),
    };

    t.app.all("/custom/**", (event) => {
      return serveStatic(event, customOptions);
    });

    const res = await t.fetch("/custom/file v2.xyz?query=123");
    expect(res.headers.get("content-type")).toBe("application/custom");
    expect(customOptions.getType).toHaveBeenCalledWith(".xyz");

    const res2 = await t.fetch("/custom/file.txt");
    expect(res2.headers.get("content-type")).toBe("text/plain");

    const res3 = await t.fetch("/custom/file");
    expect(res3.headers.get("content-type")).toBe(
      t.target === "web" ? null : "text/plain; charset=UTF-8",
    );
  });

  it("resolves the MIME type of an uppercase extension", async () => {
    const res = await t.fetch("/photos/IMG_0001.JPG");
    expect(res.headers.get("content-type")).toBe("image/jpeg");
  });

  it("uses the requested asset's MIME type for a precompressed variant", async () => {
    const files: Record<string, string> = {
      "/pre/app.js": "js",
      "/pre/app.js.gz": "js.gz",
      "/pre/app.js.br": "js.br",
      "/pre/style.css.gz": "css.gz",
      "/pre/docs/index.html.br": "html.br",
    };
    const options: ServeStaticOptions = {
      getContents: vi.fn((id) => files[id]),
      getMeta: vi.fn((id) => (files[id] ? { size: files[id].length } : undefined)),
      encodings: { gzip: ".gz", br: ".br" },
    };

    t.app.all("/pre/**", (event) => {
      return serveStatic(event, options);
    });

    for (const [path, acceptEncoding, body, type] of [
      ["/pre/app.js", "gzip", "js.gz", "text/javascript"],
      ["/pre/app.js", "br, gzip;q=0.5", "js.br", "text/javascript"],
      ["/pre/app.js", "identity", "js", "text/javascript"],
      ["/pre/style.css", "gzip", "css.gz", "text/css"],
      ["/pre/docs", "br", "html.br", "text/html"],
    ] as const) {
      const res = await t.fetch(path, { headers: { "accept-encoding": acceptEncoding } });
      expect(await res.text(), `${path} (${acceptEncoding})`).toBe(body);
      expect(res.headers.get("content-type"), `${path} (${acceptEncoding})`).toBe(type);
    }
  });

  it("does not overwrite a content-length already set on the response", async () => {
    // An explicit response content-length must win over the size derived from
    // meta — consistent with content-type / content-encoding / last-modified,
    // which are only set when not already present on the response.
    const options: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 18 })),
      headers: { "content-length": "999" },
    };

    t.app.all("/clen/**", (event) => {
      return serveStatic(event, options);
    });

    const res = await t.fetch("/clen/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-length")).toBe("999");
  });

  it("serves .wasm as application/wasm", async () => {
    // `WebAssembly.instantiateStreaming()` rejects any other type
    const res = await t.fetch("/module.wasm");
    expect(res.headers.get("content-type")).toBe("application/wasm");
  });
});

describeMatrix("serve static range", (t, { it, expect }) => {
  const digits = "0123456789";

  beforeEach(() => {
    t.app.all("/r/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ type: "text/plain", size: 10 }),
        getContents: () => digits,
      }),
    );
    t.app.all("/v/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ type: "text/plain", size: 10, etag: '"abc"', mtime: 1_700_000_000_000 }),
        getContents: () => digits,
      }),
    );
    t.app.all("/nosize/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ type: "text/plain" }),
        getContents: () => digits,
      }),
    );
    t.app.all("/empty/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ type: "text/plain", size: 0 }),
        getContents: () => "",
      }),
    );
  });

  it("advertises accept-ranges only when size is known", async () => {
    const res = await t.fetch("/r/file.txt");
    expect(res.headers.get("accept-ranges")).toBe("bytes");

    const headRes = await t.fetch("/r/file.txt", { method: "HEAD" });
    expect(headRes.headers.get("accept-ranges")).toBe("bytes");

    const noSize = await t.fetch("/nosize/file.txt");
    expect(noSize.headers.get("accept-ranges")).toBeNull();
    expect(await noSize.text()).toBe(digits);
  });

  it("serves a bounded range (bytes=a-b)", async () => {
    const res = await t.fetch("/r/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(await res.text()).toBe("2345");
  });

  it("serves an open-ended range (bytes=a-)", async () => {
    const res = await t.fetch("/r/file.txt", { headers: { range: "bytes=7-" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 7-9/10");
    expect(res.headers.get("content-length")).toBe("3");
    expect(await res.text()).toBe("789");
  });

  it("serves a suffix range (bytes=-n)", async () => {
    const res = await t.fetch("/r/file.txt", { headers: { range: "bytes=-3" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 7-9/10");
    expect(res.headers.get("content-length")).toBe("3");
    expect(await res.text()).toBe("789");
  });

  it("clamps an end past the file size to size - 1", async () => {
    const res = await t.fetch("/r/file.txt", { headers: { range: "bytes=5-100" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 5-9/10");
    expect(await res.text()).toBe("56789");
  });

  it("serves the whole file for a suffix larger than the file", async () => {
    const res = await t.fetch("/r/file.txt", { headers: { range: "bytes=-100" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-9/10");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe(digits);
  });

  it("returns 416 when the range starts at or past the end", async () => {
    const res = await t.fetch("/r/file.txt", { headers: { range: "bytes=10-12" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */10");
    expect(res.headers.get("content-length")).toBe("0");
    expect(await res.text()).toBe("");
  });

  it("returns 416 for a zero-length suffix", async () => {
    const res = await t.fetch("/r/file.txt", { headers: { range: "bytes=-0" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */10");
    expect(await res.text()).toBe("");
  });

  it("returns 416 for any range on an empty asset", async () => {
    for (const range of ["bytes=0-", "bytes=-5"]) {
      const res = await t.fetch("/empty/file.txt", { headers: { range } });
      expect(res.status, range).toBe(416);
      expect(res.headers.get("content-range"), range).toBe("bytes */0");
      expect(await res.text(), range).toBe("");
    }
  });

  it("answers HEAD with the same range headers and no body", async () => {
    const res = await t.fetch("/r/file.txt", {
      method: "HEAD",
      headers: { range: "bytes=2-5" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(await res.text()).toBe("");
  });

  it("ignores ranges it does not support (serves 200 in full)", async () => {
    for (const range of [
      "bytes=0-1,3-4",
      "items=0-1",
      "bytes=",
      "bytes=-",
      "bytes=5-2",
      "bytes=abc",
    ]) {
      const res = await t.fetch("/r/file.txt", { headers: { range } });
      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(await res.text(), range).toBe(digits);
    }
  });

  it("keeps 304 ahead of range evaluation", async () => {
    const byEtag = await t.fetch("/v/file.txt", {
      headers: { range: "bytes=0-1", "if-none-match": '"abc"' },
    });
    expect(byEtag.status).toBe(304);
    expect(byEtag.headers.get("content-range")).toBeNull();

    const byDate = await t.fetch("/v/file.txt", {
      headers: {
        range: "bytes=0-1",
        "if-modified-since": new Date(1_700_000_000_000 + 1000).toUTCString(),
      },
    });
    expect(byDate.status).toBe(304);
    expect(byDate.headers.get("content-range")).toBeNull();
  });

  it("honors If-Range with a matching strong ETag", async () => {
    const res = await t.fetch("/v/file.txt", {
      headers: { range: "bytes=2-5", "if-range": '"abc"' },
    });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
  });

  it("ignores If-Range with a weak ETag", async () => {
    const res = await t.fetch("/v/file.txt", {
      headers: { range: "bytes=2-5", "if-range": 'W/"abc"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(digits);
  });

  it("ignores If-Range with a different ETag", async () => {
    const res = await t.fetch("/v/file.txt", {
      headers: { range: "bytes=2-5", "if-range": '"xyz"' },
    });
    expect(res.status).toBe(200);
    expect(await res.text()).toBe(digits);
  });

  it("honors If-Range with the exact Last-Modified date", async () => {
    const res = await t.fetch("/v/file.txt", {
      headers: {
        range: "bytes=2-5",
        "if-range": new Date(1_700_000_000_000).toUTCString(),
      },
    });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
  });

  it("ignores If-Range with a different date", async () => {
    const res = await t.fetch("/v/file.txt", {
      headers: {
        range: "bytes=2-5",
        "if-range": new Date(1_700_000_000_000 + 1000).toUTCString(),
      },
    });
    expect(res.status).toBe(200);
    expect(await res.text()).toBe(digits);
  });

  it("ignores If-Range when no Range is sent", async () => {
    const res = await t.fetch("/v/file.txt", { headers: { "if-range": '"abc"' } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(digits);
  });

  // Current behavior, kept as-is: encoded representations ignore Range.
  it("ignores Range when meta.encoding is set (RF-09)", async () => {
    t.app.all("/enc/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ type: "text/plain", size: 10, encoding: "gzip" }),
        getContents: () => digits,
      }),
    );
    const res = await t.fetch("/enc/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(digits);
  });

  it("ignores Range for a precompressed variant (RF-09)", async () => {
    t.app.all("/gz/**", (event) =>
      serveStatic(event, {
        getMeta: (id) =>
          id === "/gz/file.txt" ? { size: 10 } : id === "/gz/file.txt.gz" ? { size: 6 } : undefined,
        getContents: (id) => (id.endsWith(".gz") ? "gzbody" : digits),
        encodings: { gzip: ".gz" },
      }),
    );
    const gzip = await t.fetch("/gz/file.txt", {
      headers: { range: "bytes=0-1", "accept-encoding": "gzip" },
    });
    expect(gzip.status).toBe(200);
    expect(gzip.headers.get("content-range")).toBeNull();
    expect(await gzip.text()).toBe("gzbody");

    // Control: the identity representation of the same asset does honor Range.
    const identity = await t.fetch("/gz/file.txt", {
      headers: { range: "bytes=2-5", "accept-encoding": "identity" },
