    expect(identity.status).toBe(206);
    expect(await identity.text()).toBe("2345");
  });

  it("keeps a user content-length on a satisfiable range (D-05)", async () => {
    t.app.all("/clen/**", (event) =>
      serveStatic(event, {
        getMeta: () => ({ size: 10 }),
