import { H3, serveStatic } from "C:/dev/runs/r27ec6c5990/src/index.ts";

const SIZE = 100 * 1024 * 1024;
const CHUNK = 64 * 1024;

function makeStream(): ReadableStream<Uint8Array> {
  let sent = 0;
  return new ReadableStream<Uint8Array>({
    pull(controller) {
      if (sent >= SIZE) return controller.close();
      const n = Math.min(CHUNK, SIZE - sent);
      controller.enqueue(new Uint8Array(n));
      sent += n;
    },
  });
}

const app = new H3().all("/**", (event) =>
  serveStatic(event, {
    getMeta: () => ({ size: SIZE }),
    getContents: () => makeStream(),
  }),
);

const start = Date.now();
let peakRss = process.memoryUsage().rss;
const timer = setInterval(() => {
  peakRss = Math.max(peakRss, process.memoryUsage().rss);
}, 10);

const res = await app.request("/video.mp4", { headers: { range: `bytes=${SIZE - 1024 * 1024}-` } });
const body = await res.arrayBuffer();
clearInterval(timer);

console.log({
  status: res.status,
  contentRange: res.headers.get("content-range"),
  bytesReceived: body.byteLength,
  ms: Date.now() - start,
  peakRssMB: Math.round(peakRss / 1024 / 1024),
});
